def get_smiles_from_name(name):
    """Convert chemical name to SMILES using PubChem."""
    try:
        # Use get_properties which is generally faster and less likely to hang
        # than retrieving full compound objects.
        props = pcp.get_properties(['CanonicalSMILES'], name, 'name')
